item.command:
/bin/zsh -lc "awk '
  FNR == 1 { files++ }
  /"'^ip route add / { v4routes++ }
  /''^ip -6 route add / { v6routes++ }
  /''^ip addr add / { v4addrs[$4]++ }
  /''^ip -6 addr add / { v6addrs[$5]++ }
  END {
    for (a in v4addrs) if (v4addrs[a] > 1) { print "duplicate IPv4", a; bad=1 }
    for (a in v6addrs) if (v6addrs[a] > 1) { print "duplicate IPv6", a; bad=1 }
    print "startup_files=" files, "static_ipv4_routes=" v4routes, "static_ipv6_routes=" v6routes
    exit bad
  }
'"' output/lab/*.startup
expected="'$(sed -n '"'s/"'^'"\\([a-z0-9_]*\\)\\[0\\]=.*/\\1/p' output/lab/lab.conf | sort -u)
actual="'$(for f in output/lab/*.startup; do basename "$f" .startup; done | sort)
[ "$expected" = "$actual" ] && echo '"'Every declared device has exactly one startup file.'
find output/lab -maxdepth 1 -type f -name 'correction.yaml' -print"

